-- Moves the last data that only lived in the app's built-in files into the database.
-- Run once in the Supabase SQL Editor. Running it again is safe: it only sets the same values.

BEGIN;

-- 1. Each stop's subscription start and close dates. The old software kept these (S_Date, C_Date)
--    so a stop applies only to the subscription it was entered for. Billing reads them.
ALTER TABLE public.discontinue ADD COLUMN IF NOT EXISTS s_date TEXT;
ALTER TABLE public.discontinue ADD COLUMN IF NOT EXISTS c_date TEXT;
ALTER TABLE public.customer_discontinue ADD COLUMN IF NOT EXISTS s_date TEXT;
ALTER TABLE public.customer_discontinue ADD COLUMN IF NOT EXISTS c_date TEXT;

