-- 2. Supplements: the Supplement screen's own rate, name and date. Rows from the old software
--    leave them empty and are priced from the supplement paper's rates, as before.
ALTER TABLE public.publicationsup ADD COLUMN IF NOT EXISTS rate NUMERIC;
ALTER TABLE public.publicationsup ADD COLUMN IF NOT EXISTS supplement_name TEXT;
ALTER TABLE public.publicationsup ADD COLUMN IF NOT EXISTS sup_date TEXT;

-- 3. This year's receipt book allotments (97 books), same columns as receiptissue20252026.
--    The open policy matches the other tables today; lock_down_database.sql removes it with the rest.
CREATE TABLE IF NOT EXISTS public."receiptissue20262027" (
  "sno" BIGINT,
  "Collect_id" BIGINT,
  "ReceiptFrom" TEXT,
  "ReceiptTo" TEXT,
  "IssueDate" TEXT,
  "RecDate" TEXT
);
ALTER TABLE public."receiptissue20262027" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public read-write for receiptissue20262027" ON public."receiptissue20262027";
CREATE POLICY "Allow public read-write for receiptissue20262027" ON public."receiptissue20262027" FOR ALL USING (true) WITH CHECK (true);

